using System.Collections.Generic;
using Astrea.BattleActions;
using UnityEngine;

namespace Astrea.GameElements;

[CreateAssetMenu(fileName = "EnemyActionLogic_AllEnemies", menuName = "Data/Battle/Logics/Enemy Action/All Enemies")]
public class EnemyActionLogic_AllEnemies : EnemyActionLogic
{
	[Header("Units")]
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	public override void ActivateAction(BattleAction battleAction, int actionAmount, GameObject source)
	{
		base.ActivateAction(battleAction, actionAmount, source);
		List<GameObject> activeCorruptedAnimals = currentCorruptedAnimals.activeCorruptedAnimals;
		if (actionAmount == EffectsValues.NO_VALUE)
		{
			battleAction.AreaCastTarget(activeCorruptedAnimals, source);
		}
		else
		{
			battleAction.AreaCastTargetAmount(activeCorruptedAnimals, actionAmount, source);
		}
	}
}
